import { defineConfig } from 'astro/config';
import tailwind from '@astrojs/tailwind';
import vercel from '@astrojs/vercel/serverless';

export default defineConfig({
  site: 'https://thevolleyballuniforms.com',
  // Canonical tags and sitemap all use trailing-slash URLs (/slug/). Force the
  // server to redirect the no-slash form to the slash form so /slug and /slug/
  // are not both 200 (duplicate URLs); the served URL then matches the canonical.
  trailingSlash: 'always',
  // The sitemap is NOT generated by @astrojs/sitemap: that integration can only
  // emit a sitemap index (sitemap-index.xml + sitemap-0.xml), and the portfolio
  // convention is one flat /sitemap.xml. It is built instead by
  // scripts/sitemap.mjs, which runs after `astro build` — see package.json.
  integrations: [tailwind()],
  // The old @astrojs/sitemap paths were live and are referenced by search
  // engines; point them at the flat sitemap instead of letting them 404.
  redirects: {
    '/sitemap-index.xml': { status: 301, destination: '/sitemap.xml' },
    '/sitemap-0.xml': { status: 301, destination: '/sitemap.xml' },
  },
  output: 'hybrid',
  adapter: vercel(),
});
